86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        normalizeAddress(ownerFieldsDto);
125	        validateRequiredFields(ownerFieldsDto);
126	        normalizeTelephone(ownerFieldsDto);
127	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
128	        rejectDuplicateHousehold(ownerFieldsDto);
129	        rejectCityAtCapacity(ownerFieldsDto.getCity());
130	        defaultRegistrationDate(ownerFieldsDto);
131	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
132	        normalizeEmail(ownerFieldsDto);
133	        HttpHeaders headers = new HttpHeaders();
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        assignCustomerCode(owner);
136	        assignHouseholdId(owner);
137	        assignNamesakeCount(owner);
138	        assignMembershipNumber(owner);
139	        assignBulkSignupWarning(owner);
140	        this.clinicService.saveOwner(owner);
141	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
142	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
152	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
153	        if (currentOwner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        normalizeEmail(ownerFieldsDto);
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
162	        currentOwner.setEmail(ownerFieldsDto.getEmail());
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
