215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    /**
232	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
233	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
234	     * Validation already rejects {@code null} values and the pattern-constrained fields
235	     * when blank, but {@code address} and {@code city} have no pattern, so a
236	     * whitespace-only value would otherwise slip through.
237	     *
238	     * @param ownerFieldsDto the submitted owner fields
239	     * @throws RequiredFieldsMissingException if any required field is missing or blank
240	     */
241	    /**
242	     * Common street-type abbreviations expanded during address normalization. Keys are the
243	     * upper-cased abbreviation tokens; values are their canonical expansions.
244	     */
245	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
246	        "ST", "STREET",
247	        "RD", "ROAD",
248	        "AVE", "AVENUE");
249	
250	    /**
251	     * Normalizes the submitted address on create and writes the canonical value back onto the
252	     * request so it is persisted, echoed back, and used for every downstream address comparison
253	     * (household duplicate detection and the household id). The value is trimmed, internal
254	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
255	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
256	     * {@code null} address is left untouched so the required-field check can report it as missing.
257	     *
258	     * @param ownerFieldsDto the submitted owner fields
259	     */
260	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
261	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
262	    }
263	
264	    /**
265	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
266	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
267	     * expanded to its full form. A {@code null} value is returned unchanged.
268	     *
269	     * @param raw the address to canonicalize, possibly {@code null}
270	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
271	     */
272	    private static String normalizeAddress(String raw) {
273	        if (raw == null) {
274	            return null;
275	        }
276	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
277	        if (collapsed.isEmpty()) {
278	            return collapsed;
279	        }
280	        String[] tokens = collapsed.split(" ");
281	        StringBuilder sb = new StringBuilder(collapsed.length());
282	        for (int i = 0; i < tokens.length; i++) {
283	            if (i > 0) {
284	                sb.append(' ');
285	            }
286	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
287	        }
288	        return sb.toString();
289	    }
290	
291	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
292	        List<String> errors = new ArrayList<>();
293	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
294	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
295	        requireText("address", ownerFieldsDto.getAddress(), errors);
296	        requireText("city", ownerFieldsDto.getCity(), errors);
297	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
298	        if (!errors.isEmpty()) {
299	            throw new RequiredFieldsMissingException(errors);
300	        }
301	    }
302	
303	    private static void requireText(String field, String value, List<String> errors) {
304	        if (value == null || value.isBlank()) {
305	            errors.add(field);
306	        }
307	    }
308	
309	    /**
310	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
311	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
312	     * and echoed back in that form.
313	     *
314	     * @param ownerFieldsDto the submitted owner fields
315	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
316	     *                                        valid E.164 number
317	     */
318	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
319	        String e164 = toE164(ownerFieldsDto.getTelephone());
320	        if (e164 == null) {
321	            throw new RequiredFieldsMissingException(List.of("telephone"));
322	        }
323	        ownerFieldsDto.setTelephone(e164);
324	    }
325	
326	    /**
327	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
328	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
329	     * and country code are present they are kept; otherwise country code {@code '+61'} is
330	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
331	     * must contain 8 to 15 digits after the {@code '+'}.
332	     *
333	     * @param raw the submitted telephone, possibly {@code null}
334	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
335	     */
336	    private static String toE164(String raw) {
337	        if (raw == null) {
338	            return null;
339	        }
340	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
341	        String digits;
342	        if (cleaned.startsWith("+")) {
343	            digits = cleaned.substring(1);
344	        } else {
345	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
346	            digits = "61" + national;
347	        }
348	        if (!digits.matches("[0-9]{8,15}")) {
349	            return null;
350	        }
351	        return "+" + digits;
352	    }
353	
354	    /**
355	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
356	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
357	     * each stored owner's telephone is normalized the same way before comparison so differing
358	     * input formats collapse to the same value.
359	     *
360	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
361	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
362	     *                                     same E.164 telephone
363	     */
364	    /**
365	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
366	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
367	     * the parts may contain whitespace or a second {@code @}.
368	     */
369	    private static final Pattern EMAIL_PATTERN =
370	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
371	
372	    /**
373	     * Normalizes the submitted email when present: the value is trimmed, required to be a
374	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
375	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
376	     *
377	     * @param ownerFieldsDto the submitted owner fields
378	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
379	     */
380	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
381	        String email = ownerFieldsDto.getEmail();
382	        if (email == null) {
383	            return;
384	        }
385	        String trimmed = email.strip();
386	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
387	            throw new InvalidEmailException(email);
388	        }
389	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
390	    }
391	
392	    /**
393	     * Establishes the effective registration date on create and rolls it onto a business day.
394	     * When the client does not supply a {@code registrationDate} it defaults to the server's
395	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
396	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
397	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
398	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
399	     * the membership number's year segment and the daily create-limit).
400	     *
401	     * @param ownerFieldsDto the submitted owner fields
402	     */
403	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
404	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
405	        if (effective == null) {
406	            effective = LocalDate.now();
407	        }
408	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
409	    }
410	
411	    /**
412	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
413	     * following Monday; any weekday is returned unchanged.
414	     *
415	     * @param date the date to adjust
416	     * @return the same date when it is a weekday, otherwise the next Monday
417	     */
418	    private static LocalDate toBusinessDay(LocalDate date) {
419	        return switch (date.getDayOfWeek()) {
420	            case SATURDAY -> date.plusDays(2);
421	            case SUNDAY -> date.plusDays(1);
422	            default -> date;
423	        };
424	    }
425	
426	    /**
427	     * Assigns the owner's {@code customerCode} on create, formatted
428	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
429	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
430	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
431	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
432	     *
433	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
434	     */
435	    private void assignCustomerCode(Owner owner) {
436	        String city = owner.getCity();
437	        String lastName = owner.getLastName();
438	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
439	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
440	        long sequence = this.clinicService.findAllOwners().stream()
441	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
442	            .count() + 1;
443	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
444	    }
445	
446	    /**
447	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
448	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
449	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
450	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
451	     * canonicalized fields, every owner in the same household — including one joining an existing
452	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
453	     * order.
454	     *
455	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
456	     */
457	    private void assignHouseholdId(Owner owner) {
458	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
459	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
460	    }
461	
462	    /**
463	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
464	     * already share this owner's {@code firstName} and {@code lastName}, compared
465	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
466	     * pre-existing namesakes.
467	     *
468	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
469	     */
470	    private void assignNamesakeCount(Owner owner) {
471	        String firstName = owner.getFirstName();
472	        String lastName = owner.getLastName();
473	        long count = this.clinicService.findAllOwners().stream()
474	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
475	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
476	            .count();
477	        owner.setNamesakeCount((int) count);
478	    }
479	
480	    /**
481	     * Assigns the owner's {@code membershipNumber} on create, formatted
482	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
483	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
484	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
485	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
486	     *
487	     * @param owner the owner being created (with its {@code customerCode} and
488	     *              {@code registrationDate} already set)
489	     */
490	    private void assignMembershipNumber(Owner owner) {
491	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
492	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
493	    }
494	
495	    /**
496	     * The number of owners that must already carry a registration date before a subsequent
497	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
498	     * once the count of owners already registered on that day <em>exceeds</em> this value.
499	     */
500	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
501	
502	    /**
503	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
504	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
505	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
506	     * existing owners before this one is persisted, so it reflects only the owners already
507	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
508	     *
509	     * @param owner the owner being created (with its {@code registrationDate} already set)
510	     */
511	    private void assignBulkSignupWarning(Owner owner) {
512	        LocalDate registrationDate = owner.getRegistrationDate();
513	        long count = this.clinicService.findAllOwners().stream()
514	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
515	            .count();
516	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
517	    }
518	
519	    /**
520	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
521	     *
522	     * @param value the string to hash
523	     * @return the 64-character lower-case hex digest
524	     */
525	    private static String sha256Hex(String value) {
526	        try {
527	            byte[] digest = MessageDigest.getInstance("SHA-256")
528	                .digest(value.getBytes(StandardCharsets.UTF_8));
529	            StringBuilder sb = new StringBuilder(digest.length * 2);
530	            for (byte b : digest) {
531	                sb.append(String.format("%02x", b));
532	            }
533	            return sb.toString();
534	        }
535	        catch (NoSuchAlgorithmException e) {
536	            throw new IllegalStateException("SHA-256 not available", e);
537	        }
538	    }
539	
540	    private void rejectDuplicateTelephone(String normalizedTelephone) {
541	        boolean duplicate = this.clinicService.findAllOwners().stream()
542	            .map(Owner::getTelephone)
543	            .map(OwnerRestControllerV1::toE164)
544	            .filter(telephone -> telephone != null)
545	            .anyMatch(normalizedTelephone::equals);
546	        if (duplicate) {
547	            throw new DuplicateTelephoneException(normalizedTelephone);
548	        }
549	    }
550	
551	    /**
552	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
553	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
554	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
555	     * still counts as the same household. The check is skipped when the request opts in via
556	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
557	     * the existing one.
558	     *
559	     * @param ownerFieldsDto the submitted owner fields
560	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
561	     *                                     last name and address and the request did not opt in
562	     */
563	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
564	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
565	            return;
566	        }
567	        String lastName = collapse(ownerFieldsDto.getLastName());
568	        String address = collapse(ownerFieldsDto.getAddress());
569	        boolean duplicate = this.clinicService.findAllOwners().stream()
570	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
571	                && collapse(owner.getAddress()).equals(address));
572	        if (duplicate) {
573	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
574	        }
575	    }
576	
577	    /**
578	     * The maximum number of owners permitted in a single city. A create is rejected once the
579	     * owner's city already contains this many owners.
580	     */
581	    private static final long CITY_CAPACITY = 50;
582	
583	    /**
584	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
585	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
586	     * before this owner is persisted.
587	     *
588	     * @param city the submitted city
589	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
590	     */
591	    private void rejectCityAtCapacity(String city) {
592	        long count = this.clinicService.findAllOwners().stream()
593	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
594	            .count();
595	        if (count >= CITY_CAPACITY) {
596	            throw new CityAtCapacityException(city);
597	        }
598	    }
599	
600	    /**
601	     * The maximum number of owners permitted to be created in a single day. A create is
602	     * rejected once this many owners already carry today's {@code registrationDate}.
603	     */
604	    private static final long DAILY_LIMIT = 100;
605	
606	    /**
607	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
608	     * business day as their {@code registrationDate}. The day counted against is this create's
609	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
610	     * so owners are counted per adjusted business day. The count is taken before this owner is
611	     * persisted.
612	     *
613	     * @param businessDay the effective, business-day-adjusted registration date of this create
614	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
615	     */
616	    private void rejectDailyLimit(LocalDate businessDay) {
617	        long count = this.clinicService.findAllOwners().stream()
618	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
619	            .count();
620	        if (count >= DAILY_LIMIT) {
621	            throw new DailyOwnerLimitExceededException(businessDay);
622	        }
623	    }
624	
625	    /**
626	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
627	     * every internal run of whitespace is collapsed to a single space, and the result is
628	     * lower-cased. A {@code null} value collapses to the empty string.
629	     *
630	     * @param value the value to canonicalize, possibly {@code null}
631	     * @return the collapsed, lower-cased value
632	     */
633	    private static String collapse(String value) {
634	        if (value == null) {
635	            return "";
636	        }
637	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
638	    }
639	
640	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
641	    @Override
642	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
643	        Owner owner = this.clinicService.findOwnerById(ownerId);
644	        if (owner != null) {
645	            Pet pet = owner.getPet(petId);
646	            if (pet != null) {
647	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
648	            }
649	        }
650	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
651	    }
652	}
